export const componentAttrs = (componentName, data) => (
    [
        `data-component="${componentName}"`,
        containerModifiersAttr(data)
    ]
    .filter(Boolean)
    .join(' ')
);

export function containerModifiersAttr(props = {}) {
    const mods = containerModifiers(props);
    return mods.length ? `data-cm="${mods.join(':')}"` : '';
}

export function containerModifiers(props = {}) {
    const { containerModifiers: { variant, verticalSpace, fullwidthBackground } = {}} = props;
    return [
        variant,
        verticalSpace,
        fullwidthBackground ? 'fullwidth-background' : ''
    ].filter(Boolean);
}